#include <set>
#include <iostream>

struct MyInt {
    int value;
    // Define a non-standard comparison
    bool operator<(const MyInt& other) const {
        return value < other.value;
    }
};

int main() {
    std::set<MyInt> s;
    MyInt a = {10};
    MyInt b = {10};

    s.insert(a);
    s.insert(b); // Equivalence check: !(a<b || b<a) -> !(false || false) -> true

    // Size is 1 because 'a' and 'b' are equivalent based on operator<
    std::cout << s.size(); // Output: 1
}
